
from html.parser import HTMLParser
import re
import inspect
import os

def is_centering(tag, attrs):
    if tag.lower() == "center":
        return True

    return tag == "p" and any([
        (t.lower() == "align" and v.lower() == "center") or 
        (t.lower() == "style" and "text-align: center" in v.lower())
        for (t, v) in attrs])

# generated by robots
def convert_all_citations_to_footnotes(text: str) -> str:
    # 1. Negative lookahead `(?!\s*\d\s*\))` explicitly blocks single digits like (1), (2)
    # 2. Require structural citation features:
    #    - ibid (including LaTeX wrapped like \textit{Ibid.})
    #    - Standalone Roman numerals: \b[ivxIVX]+\b
    #    - Explicit page/vol indicators: p., pp., vol., ch., v., no.
    #    - Volume/page pairs: "1, 5" or "4:12" or "1007" (multi-digit numbers)
    #    - Author/Title followed by a number: [A-Za-z]+\s*,\s*\d+
    citation_trigger = (
        r"(?!\s*\d*\s*\))"  # Exclude single digits like (1)
        r"(?:\\?\w*{?ibid\.?}?"
        r"|\b[ivxIVX]+\b"
        r"|(?:p\.|pp\.|v\.|ch\.|no\.|vol\.|l\.c\.)\s*\d+"
        r"|\b\d+[\s,:]+\d+\b"
        r"|\b\d{2,}\b"
        r"|[A-Za-z\s]+,\s*\d+)"
    )
    
    parenthesis_pattern = rf"([.,;:!?])?\s*\(\s*(cf\.\s+)?([^)]*?{citation_trigger}[^)]*)\)([.,;:!?])?"
    
    def replacer(match):
        pre_punct = match.group(1) or ""
        cf_prefix = match.group(2) or "" 
        citation_block = match.group(3)
        post_punct = match.group(4) or ""
        
        final_punct = post_punct if post_punct else pre_punct
        
        clean_cit = re.sub(r"\s+", " ", citation_block).strip()
        
        if cf_prefix and not clean_cit.lower().startswith("cf."):
            clean_cit = f"cf. {clean_cit}"
            
        return f"{final_punct}\\footnote{{{clean_cit}}}"

    return re.sub(parenthesis_pattern, replacer, text, flags=re.IGNORECASE)

# generated by robots
def repair_broken_paragraphs(text: str) -> str:
    # This regex matches:
    # 1. ([a-z0-9,;]) -> A lowercase letter, digit, comma, or semicolon (Group 1)
    # 2. \s*\n+\s*     -> One or more newlines surrounded by any spacing/indentation
    # 3. ([a-z])      -> A lowercase letter starting the next line (Group 2)
    pattern = r"([a-z0-9,;])\s*\n+\s*([a-z])"
    
    # We replace the newline and padding with a single space, keeping the boundary characters
    return re.sub(pattern, r"\1 \2", text)

# generated by robots
def move_punctuation_inside_quotes(text: str) -> str:
    # This regex matches:
    # 1. (['"”’])            -> Group 1: A closing quote mark (single, double, or curly)
    # 2. \s*                 -> Zero or more spaces
    # 3. (?<!\.\s)(?<!\.)    -> Negative lookbehinds: Ensure we aren't matching part of an ellipsis
    # 4. ([.,;:!?])          -> Group 2: The trailing punctuation mark
    # 5. (?!\s*\.)(?!\.)     -> Negative lookaheads: Ensure the punctuation isn't followed by more dots
    pattern = r"(['\"”’])\s*(?<!\.\s)(?<!\.)([.,;:!?])(?!\s*\.)(?!\.)"
    
    # Replacement r"\2\1" places the punctuation (Group 2) before the quote (Group 1)
    return re.sub(pattern, r"\2\1", text)

class VaticanTextExtractor(HTMLParser):

    def __init__(self, debug=False, footnotes="endnotes", replacements = {}, triggers = [], author = "", **kwargs):
        super().__init__()
        self.recording = False
        self.debug = debug

        self.state = ""
        self.title = []
        self.body = []
        self.footnotes = []
        self.footnote_format = footnotes
        self.replacements = replacements
        self.triggers = triggers
        self.author = author.replace("Pope", "").strip()

        self.tag_stack = []

    def set_state(self, state, offset=0):
        self.log(f"set_state: {state}", 2+offset)
        self.state = state
    
    def check_state_update(self, tag=None, attrs={}, data=""):
        for trigger in self.triggers:

            if "old" in trigger and self.state != trigger["old"]:
                continue

            if "tag" in trigger and not (tag == trigger["tag"] and all((k, v) in attrs for (k, v) in trigger.get("attrs", {}).items())):
                continue
        
            if "data" in trigger and data.strip() != trigger["data"]:
                continue

            self.log(f"trigger: {tag}, {attrs}, {data}")
            state = trigger.get("state", "")
            if self.state != state:
                self.set_state(state, offset=1)
            if self.recording != (state != ""):
                self.set_recording(state != "", offset=1)

            return

    def set_recording(self, state, offset=0):
        self.log(f"set_recording: {state}", 2+offset)
        self.recording = state
        self.tag_stack = []
    
    def log(self, message, depth=1):
        if self.debug:
            caller = inspect.stack()[depth]
            print(f"{os.path.basename(caller.filename)} {caller.lineno}\t - {message}")
    
    def get_tag(self):
        if len(self.tag_stack):
            return self.tag_stack[-1][0]
        return ""
    
    def has_tag(self, *tags):
        return any(t[0] in tags for t in self.tag_stack)

    def has_centering(self):
        return any(is_centering(tag, attrs) for (tag, attrs) in self.tag_stack)

    def write(self, data):
        section = self.title if self.state == "title" else self.body if self.state == "body" else self.footnotes if self.state == "footnotes" else []

        if len(section) == 0:
            section.append("")
        
        start, end = "", ""
        if self.has_tag("b", "strong") and self.state != "footnotes":
            self.log("textbf")
            start += "\\textbf{"
            end += "}"
        if self.has_tag("i"):
            self.log("textit")
            start += "\\textit{"
            end += "}"

        if start != "":
            if re.match(r'^\s.*', data):
                start = " " + start
            if re.match(r'.*\s$', data):
                end += " "
            data = data.strip()
        
        section[-1] += start + data + end
    
    def append(self):
        section = self.title if self.state == "title" else self.body if self.state == "body" else self.footnotes if self.state == "footnotes" else []

        # Center roman numeral sections
        if len(section) > 0:
            if re.match(r'^(\s*\\text(it)?(bf)?{)*[IVXCM]+}*$', section[-1].strip()):
                self.log(f"placespecialblock - {section[-1]}")
                section[-1] = f"\\placespecialblock{{\\centering {section[-1].strip()}}}"
            elif section[-1].startswith("\\text"):
                self.log(f"placespecialblock - {section[-1]}")
                section[-1] = f"\\placespecialblock{{{section[-1].strip()}}}"

        if len(section) > 0 and section[-1].strip() == "":
            return
        
        section.append("")

    def handle_data(self, data):
        self.check_state_update(data=data)

        if self.recording and data.strip() != "":
            if self.state in ["title", ""] and not self.has_centering():
                self.log(f"current title: {self.title}")
                self.set_state("body")

            if self.state in ["title", "body"]:
                self.log(f"{self.state} += {data}")
                if self.has_tag("sup"):
                    data = f"({data})"

                self.write(data)
            elif self.state == "footnotes":
                self.log(f"{self.state} += {data}")

                if self.has_tag("li"):
                    self.write(data)
                
                elif not "REFERENCES" in data and not "NOTES" in data:
                    self.write(data)
    
    def handle_starttag(self, tag, attrs):
        self.check_state_update(tag=tag, attrs=attrs)

        # We look for the main content container to avoid header/footer navigation links
        attrs_dict = dict(attrs)
        if attrs_dict.get("class") == "text parbase container vaticanrichtext":
            self.set_recording(True)
        elif attrs_dict.get("class") == "entry-content":
            self.set_recording(True)
            self.set_state("body")

        elif self.recording:
            self.tag_stack.append((tag, attrs))

            if self.state == "" and is_centering(tag, attrs):
                self.set_state("title")

            if self.state == "body" and is_centering(tag, attrs):
                self.write("\\placespecialblock{\\centering ")
            
            if len(self.body) > 1 and (tag == "hr" or tag == "footer"):
                self.set_state("footnotes")

    def handle_endtag(self, tag):
        if self.recording:
            if len(self.tag_stack) == 0:
                self.set_recording(False)
                return

            attrs = self.tag_stack[-1][-1]
            self.log(f"end_tag:\t {tag} {attrs}")
        
            if self.state == "body" and is_centering(tag, attrs):
                if self.body[-1] == "\\placespecialblock{\\centering ":
                    self.body.pop()
                else:
                    self.write("}")

            if tag in ["br", "p", "li"]:
                self.append()

            if self.tag_stack[-1][0] == tag:
                self.tag_stack.pop()
            else:
                print("ERROR:", tag, self.tag_stack)
                self.set_recording(False)

    def get_clean_text(self, numbered_footnotes=False):
        while len(self.body) > 0 and self.body[-1].strip() == "":
            self.body.pop()

        while len(self.body) > 0 and self.body[-1].strip().startswith("\\placespecialblock{\\centering ") and self.author.upper() in self.body[-1]:
            self.body.pop()

        text = "\n\n".join(self.body)
        self.log(f"formatting {len(self.body)} entries")

        for old, new in self.replacements.items():
            text = text.replace(old, new)
        text = text.replace("—", "---").replace("–", "--")
        text = text.replace("  ", " ").strip()

        if "parenthetical" in self.footnote_format:
            text = convert_all_citations_to_footnotes(text)

        if "endnotes" in self.footnote_format:
            for idx, footnote in self.get_footnotes(numbered=numbered_footnotes).items():
                self.log(f"footnote {idx}: {footnote}")
                footnote = " " + footnote.replace("\\text", "\\\\text").strip()
                text = re.sub(rf'\s*[\[\(]{idx}\s?[\]\)]\.', rf".\\footnote{{{footnote}}} ", text, 1)
                text = re.sub(rf'\s*[\[\(]{idx}\s?[\]\)]', rf"\\footnote{{{footnote}}} ", text, 1)

        text = repair_broken_paragraphs(text)
        text = move_punctuation_inside_quotes(text)
        text = text.replace("  ", " ").strip()
        text = text.replace("”", '"').replace("“", '"')
        text = re.sub(r"(?<!\b)'\b(?=[^'(\"\b)]*\b\.?\,?\")", '``', text)
        text = re.sub(r"(?<=\s)\"\s?(?=[^'(\"\b)]*\b\.?\,?\")", '``', text)
        text = re.sub(r'"\b', '``', text)
        text = re.sub(r'(?<!\b)\'\b', '`', text)
        text = re.sub(r'\b"', "''", text)
        text = re.sub(r'(\))(\s+)([\.\,\;\:])', r'\1\3', text)

        return text

        
    def get_footnotes(self, numbered=False):
        if not numbered and not re.match(rf"^\s?\(?1\)?\.?\s.*", self.footnotes[0]):
            return {k+1: re.sub(rf"^\(?{k+1}\)?\.?(?!\d)\s*", "", v) for k, v in enumerate(self.footnotes)}

        self.log(f"footnotes: {self.footnotes}")

        out = {}
        idx = 0
        while idx < len(self.footnotes):
            footnote = self.footnotes[idx].strip()

            if re.match(rf"\s\(?{idx+2}\)?\.?\s", footnote):
                parts = footnote.split(f" {idx+2}. ")
                footnote = parts[0]
                self.footnotes.insert(idx+1, f"{idx+2}. {parts[1]}")
            
            if not re.match(rf"^\(?{idx+1}\)?\.?(?!\d)", footnote):
                self.footnotes.pop(idx)
                continue
            
            out[idx+1] = re.sub(rf"^\s*\(?{idx+1}\)?\.?(?!\d)\s*", "", footnote)
            idx += 1
        return out
    